const courses = [
 {id:'crs_web',title:'Web development foundations',category:'Development',description:'Build your first website, from a blank page to the browser.',instructor:'Maya Chen',duration:'2 hours',price:499,bg:'#dce9f0',ink:'#537b94',symbol:'</>',code:true,caption:'BUILD FOR THE WEB',lessons:['How the web works','Structure with HTML','Style with CSS','Bring it to life with JavaScript']},
 {id:'crs_python',title:'Python, from the beginning',category:'Development',description:'Write clear code and turn everyday problems into programs.',instructor:'Arun Patel',duration:'3 hours',price:699,bg:'#efe8cc',ink:'#998545',symbol:'Py',caption:'THINK. CODE. REPEAT.',lessons:['Variables and types','Conditions and loops','Functions and reuse','Working with collections']},
 {id:'crs_design',title:'The essentials of UI design',category:'Design',description:'Make digital experiences feel simple, clear, and considered.',instructor:'Elena Brooks',duration:'2 hours',price:599,bg:'#e9dfec',ink:'#94709e',symbol:'Aa',caption:'FORM MEETS FUNCTION',lessons:['Visual hierarchy','Type and spacing','Color and contrast','Designing a useful screen']},
 {id:'crs_api',title:'REST APIs made practical',category:'Development',description:'Connect your ideas with requests, responses, and good API design.',instructor:'Alex Morgan',duration:'2.5 hours',price:799,bg:'#dae8dc',ink:'#5e896a',symbol:'{ }',code:true,caption:'A CONVERSATION IN CODE',lessons:['Resources and URIs','HTTP methods','Requests and responses','Status codes and errors']},
 {id:'crs_sql',title:'Find the story in your data',category:'Data',description:'Use SQL to ask better questions and make sense of your data.',instructor:'Priya Shah',duration:'3 hours',price:649,bg:'#f0e0d4',ink:'#af8263',symbol:'▥',caption:'ASK BETTER QUESTIONS',lessons:['Tables and records','Selecting and filtering','Grouping and aggregation','Joining related tables']},
 {id:'crs_git',title:'A friendly introduction to Git',category:'Development',description:'Save your work, explore branches, and collaborate with confidence.',instructor:'Sam Rivera',duration:'1.5 hours',price:399,bg:'#dee2ef',ink:'#7382ad',symbol:'↗',caption:'MAKE PROGRESS TOGETHER',lessons:['Repositories and commits','Branches and merging','Remotes and collaboration','A reliable daily workflow']}
];
const escapeHtml = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let category='All', query='', view='courses';
function card(c){return `<article class="course-card"><div class="course-art" style="--art-bg:${c.bg};--art-ink:${c.ink}"><span class="art-caption">${c.caption}</span><span class="art-icon ${c.code?'code':''}">${escapeHtml(c.symbol)}</span><span class="art-number">4 LESSONS / AT YOUR PACE</span></div><div class="card-content"><div class="card-tags"><span class="tag">${c.category}</span><span class="level">Beginner friendly</span></div><h3>${c.title}</h3><p>${c.description}</p><div class="meta"><span>◷ ${c.duration}</span><span>♙ ${c.instructor}</span></div><div class="card-bottom"><span class="price">₹${c.price}<small>one-time</small></span><button class="view-button" data-course="${c.id}">View course ↗</button></div></div></article>`;}
function renderCatalog(){const filtered=courses.filter(c=>(category==='All'||category===c.category)&&`${c.title} ${c.category} ${c.description} ${c.instructor}`.toLowerCase().includes(query.toLowerCase()));document.querySelector('#course-grid').innerHTML=filtered.map(card).join('')||'<div class="empty"><h2>No courses found</h2><p>Try another keyword or choose All courses.</p></div>';document.querySelector('#result-count').textContent=`${filtered.length} course${filtered.length===1?'':'s'} to explore`;}
renderCatalog();
const main=document.querySelector('#main'), catalogHTML=main.innerHTML, dialog=document.querySelector('#course-dialog');
const storageKey='lumen-round2-v1';
let enrollments={};
try{const saved=JSON.parse(localStorage.getItem(storageKey)||'{}');for(const c of courses){const e=saved[c.id];if(e&&typeof e.id==='string'&&['pending_payment','active'].includes(e.status)&&Array.isArray(e.completed)){enrollments[c.id]={...e,completed:[...new Set(e.completed.filter(i=>Number.isInteger(i)&&i>=0&&i<4))],submission:typeof e.submission==='string'?e.submission:null};}}}catch{}
const requests=[];
function save(){try{localStorage.setItem(storageKey,JSON.stringify(enrollments));}catch{toast('Progress works for this visit; browser storage is unavailable.');}updateCount();}
function updateCount(){document.querySelector('#enrollment-count').textContent=Object.keys(enrollments).length;}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),3600);}
function api(method,path,body={}){
 const url=new URL(path,'https://demo.local');const parts=url.pathname.split('/').filter(Boolean);let status=200,data;
 const fail=(code,message)=>{status=code;data={error:{code:message.toUpperCase().replace(/[^A-Z0-9]+/g,'_'),message}};};
 const c=courses.find(c=>c.id===parts[2]);
 if(method==='GET'&&url.pathname==='/api/courses'){const q=(url.searchParams.get('q')||'').toLowerCase();data={courses:courses.filter(c=>`${c.title} ${c.category} ${c.description} ${c.instructor}`.toLowerCase().includes(q))};}
 else if(method==='GET'&&parts.length===3&&parts[1]==='courses'){if(c)data=c;else fail(404,'Course not found');}
 else if(method==='POST'&&url.pathname==='/api/enrollments'){
  const course=courses.find(c=>c.id===body.courseId);
  if(!body.courseId||!body.studentId)fail(400,'studentId and courseId are required');
  else if(body.studentId!=='stu_001')fail(403,'This demo supports stu_001 only');
  else if(!course)fail(404,'Course not found');
  else if(enrollments[course.id])fail(409,'Student is already enrolled');
  else{status=201;const e={id:`enr_${crypto.randomUUID()}`,studentId:'stu_001',courseId:course.id,status:'pending_payment',completed:[],submission:null};enrollments[course.id]=e;data={enrollmentId:e.id,studentId:e.studentId,courseId:e.courseId,status:e.status,payment:{amount:course.price,currency:'INR'},createdAt:new Date().toISOString()};save();}
 }
 else if(method==='POST'&&url.pathname==='/api/payments'){
  const e=Object.values(enrollments).find(e=>e.id===body.enrollmentId);
  if(!body.enrollmentId)fail(400,'enrollmentId is required');else if(!e)fail(404,'Enrollment not found');else if(e.status==='active')fail(409,'Payment already completed');else if(body.demoResult!=='success')fail(422,'Simulated payment declined');else{status=201;e.status='active';data={paymentId:`pay_${crypto.randomUUID()}`,enrollmentId:e.id,status:'succeeded',enrollmentStatus:'active',simulated:true};save();}
 }
 else if(method==='GET'&&parts[1]==='students'&&parts[3]==='progress'){
  if(parts[2]!=='stu_001')fail(403,'Student access denied');else data={studentId:'stu_001',courses:Object.values(enrollments).map(e=>({courseId:e.courseId,status:e.status,completedLessons:e.completed.length,totalLessons:4,progressPercent:e.completed.length*25,assignmentSubmitted:!!e.submission}))};
 }
 else if(['GET','PUT','POST'].includes(method)&&parts[1]==='courses'&&['content','progress','assignments'].includes(parts[3])){
  const e=c&&enrollments[c.id];
  if(!c)fail(404,'Course not found');else if(!e||e.status!=='active')fail(403,'Complete enrollment and payment to access this course');
  else if(method==='GET'&&parts[3]==='content')data={courseId:c.id,lessons:c.lessons,assignmentId:`asg_${c.id}`};
  else if(method==='PUT'&&parts[3]==='progress'){
   if(!Number.isInteger(body.lessonIndex)||body.lessonIndex<0||body.lessonIndex>=4)fail(422,'lessonIndex must be between 0 and 3');else{if(!e.completed.includes(body.lessonIndex))e.completed.push(body.lessonIndex);data={courseId:c.id,completedLessons:e.completed.length,totalLessons:4,progressPercent:e.completed.length*25};save();}
  }
  else if(method==='POST'&&parts[3]==='assignments'&&parts[4]===`asg_${c.id}`&&parts[5]==='submissions'){
   if(typeof body.content!=='string'||!body.content.trim()||body.content.length>10000)fail(422,'Write an answer between 1 and 10000 characters');else if(e.submission)fail(409,'Assignment already submitted');else{status=201;e.submission=body.content.trim();e.submittedAt=new Date().toISOString();data={submissionId:`sub_${crypto.randomUUID()}`,assignmentId:parts[4],studentId:'stu_001',status:'submitted',submittedAt:e.submittedAt};save();}
  }else fail(404,'Endpoint not found');
 }else fail(404,'Endpoint not found');
 const result={status,data};requests.unshift({method,path,status,body,data,time:new Date().toLocaleTimeString()});requests.splice(40);if(view==='api')renderApi();return result;
}
function showView(next){view=next;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));document.querySelector('#breadcrumb').textContent={courses:'Explore courses',learning:'My learning',api:'Round 2 API design'}[view];if(view==='courses'){main.innerHTML=catalogHTML;document.querySelector('#search').value=query;document.querySelectorAll('[data-category]').forEach(b=>b.classList.toggle('active',b.dataset.category===category));renderCatalog();}else if(view==='learning'){api('GET','/api/students/stu_001/progress');renderLearning();}else renderApi();window.location.hash=view;}
function openDialog(html){document.querySelector('#dialog-content').innerHTML=html;if(!dialog.open)dialog.showModal();}
function dialogTop(title,tag='COURSE OVERVIEW'){return `<div class="dialog-top"><div><div class="eyebrow">${tag}</div><h2 id="dialog-title">${title}</h2></div><button class="close" data-action="close" aria-label="Close dialog">×</button></div>`;}
function showCourse(id){const res=api('GET',`/api/courses/${id}`);if(res.status!==200)return toast(res.data.error.message);const c=res.data,e=enrollments[id];if(e?.status==='active'){showClassroom(id);return;}openDialog(`${dialogTop(c.title)}<div class="dialog-body"><span class="tag">${c.category}</span><p>${c.description}</p><div class="meta"><span>${c.instructor}</span><span>${c.duration}</span><span>4 lessons</span></div><h3 class="small-heading">What you’ll learn</h3><ol class="syllabus">${c.lessons.map((l,i)=>`<li class="lesson-row"><span><span class="lesson-index">${String(i+1).padStart(2,'0')}</span>${l}</span><span class="muted">Lesson</span></li>`).join('')}</ol><div class="notice">Includes a short reading for each lesson and one written assignment. Enroll and complete a demo payment to access the course.</div></div><div class="dialog-footer"><span class="price">₹${c.price}<small>one-time · demo only</small></span><button class="primary" data-action="${e?'checkout':'enroll'}" data-id="${id}">${e?'Continue to demo payment':'Enroll in course'} →</button></div>`);}
function enroll(id){const r=api('POST','/api/enrollments',{studentId:'stu_001',courseId:id});if(r.status===201){toast('Enrolled. Complete demo payment to start learning.');showCheckout(id);}else toast(r.data.error.message);}
function showCheckout(id){const c=courses.find(c=>c.id===id);openDialog(`${dialogTop('One step away.','DEMO CHECKOUT')}<div class="dialog-body"><p>You’re enrolling in <strong>${c.title}</strong>.</p><div class="payment-summary"><div><strong>₹${c.price}</strong><p>One-time course access</p></div><span class="tag">INR</span></div><div class="notice">This is a simulated payment. No money is charged and no card details are needed.</div><p class="muted">Try a successful or declined payment to demonstrate the enrollment sequence.</p><div id="payment-error" role="alert"></div></div><div class="dialog-footer"><button class="secondary" data-action="decline" data-id="${id}">Simulate decline</button><button class="primary" data-action="pay" data-id="${id}">Simulate payment · ₹${c.price} →</button></div>`);}
function pay(id,success){const r=api('POST','/api/payments',{enrollmentId:enrollments[id].id,demoResult:success?'success':'declined'});if(r.status===201){toast('Demo payment complete. Your course is ready.');showClassroom(id);if(view==='learning')renderLearning();}else document.querySelector('#payment-error').innerHTML=`<p class="error-text">${escapeHtml(r.data.error.message)}. Your course is still locked. Try again.</p>`;}
function showClassroom(id){const r=api('GET',`/api/courses/${id}/content`);if(r.status!==200)return toast(r.data.error.message);const c=courses.find(c=>c.id===id),e=enrollments[id];openDialog(`${dialogTop(c.title,'YOUR CLASSROOM')}<div class="dialog-body"><div class="meta"><span>${c.instructor}</span><span>${c.duration}</span></div><div class="progress-track"><div class="progress-fill" style="width:${e.completed.length*25}%"></div></div><span class="muted">${e.completed.length} of 4 lessons completed · ${e.completed.length*25}%</span><h3 class="small-heading">Course lessons</h3><ol class="syllabus">${c.lessons.map((l,i)=>`<li class="lesson-row"><span><span class="lesson-index">${e.completed.includes(i)?'✓':String(i+1).padStart(2,'0')}</span>${l}</span><button data-action="lesson" data-id="${id}" data-index="${i}">${e.completed.includes(i)?'Review':'Read lesson'} →</button></li>`).join('')}</ol><h3 class="small-heading">Put your learning into practice</h3><div class="lesson-row"><span>Course assignment <span class="muted">· ${e.submission?'Submitted ✓':'Written response'}</span></span><button data-action="assignment" data-id="${id}">${e.submission?'View answer':'Open assignment'} →</button></div><p class="muted">Progress measures completed lessons. Assignment status is tracked separately.</p></div><div class="dialog-footer"><span class="muted">Learn at your own pace.</span><button class="secondary" data-action="close">Back to workspace</button></div>`);}
const lessonContent={
 crs_web:[['A browser asks, a server answers.','A website begins with a request. The browser requests a document from a server using HTTP, then renders HTML and loads the styles and scripts it references.','HTML describes structure, CSS controls presentation, and JavaScript adds behavior.','Browser → GET /index.html → Server → HTML response'],['Give content a meaningful structure.','HTML elements describe the purpose of content. Use a heading for a title, a paragraph for a thought, and a button for an action.','Semantic elements help both people and assistive technology understand your page.','<main>\n  <h1>My first website</h1>\n  <p>A small beginning.</p>\n</main>'],['Make the structure readable.','CSS applies styles to selected elements. Start with spacing, a readable font size, and sufficient contrast. Use a flexible layout so content fits smaller screens.','The box model combines content, padding, border, and margin.','main { max-width: 800px; margin: auto; padding: 24px; }'],['Respond to a student’s action.','JavaScript can listen to events and update the page. Keep state separate from presentation so the same action always produces the expected result.','Use textContent for user-provided text instead of inserting raw HTML.','button.addEventListener("click", () => {\n  message.textContent = "Hello, learner!";\n});']],
 crs_python:[['Name a value.','A variable refers to a value. Python supports strings, integers, floating-point numbers, and booleans. Choose names that describe the meaning of a value.','Use type(value) to inspect a value’s type.','student = "Alex"\ncompleted_lessons = 0\nis_enrolled = True'],['Choose and repeat.','An if statement chooses a path based on a condition. A for loop visits each item in a collection. Indentation defines the body of each block.','A loop lets you apply one operation consistently to many values.','for lesson in ["Basics", "Functions"]:\n    print(lesson)'],['Give a task a name.','A function groups a reusable operation. Parameters are the inputs, and a return value is the result. Keep each function focused on one clear task.','Separating calculation from printing makes a function easier to reuse.','def progress(completed, total):\n    return completed / total * 100\n\nprint(progress(2, 4))  # 50.0'],['Collect related values.','Lists hold ordered items. Dictionaries map keys to values. Use a list for course lessons and a dictionary for a student record.','Access a dictionary entry by its key and a list item by its index.','student = {"name": "Alex", "course": "Python"}\nlessons = ["Types", "Loops", "Functions"]\nprint(student["name"], lessons[0])']],
 crs_design:[['Guide the eye.','Visual hierarchy makes the most useful information easiest to find. Size, weight, position, and spacing help people recognize what matters first.','Give a screen one clear primary action.','Title → Supporting description → Primary action'],['Create breathing room.','Typography and spacing make content readable. Use a small, consistent type scale and align related items. Space groups farther apart than items within a group.','Readable body text needs comfortable line height and a sensible line length.','Heading: 28px\nBody: 16px / 1.6 line height\nSpacing: 8, 16, 24, 32px'],['Use color with purpose.','Color can indicate an action or status, but it should work together with labels and icons. Ensure text is easy to distinguish from its background.','Never rely only on color to communicate success or failure.','Success: ✓ Submitted\nFailure: Payment declined — try again'],['Design around a task.','Start with the user’s goal. Put the necessary information and controls in the order people need them, then remove distractions.','For enrollment, show the course, price, payment step, and access confirmation.','Course details → Enroll → Payment → Course access']],
 crs_api:[['Model a resource.','A REST API represents resources with URIs. Courses, enrollments, and submissions are resources. Use nouns and stable identifiers in paths.','A URI identifies the resource; the HTTP method describes the operation.','GET /api/courses/crs_web'],['Choose the right method.','GET reads a resource. POST creates a resource or starts an operation. PUT replaces a resource’s representation and is idempotent. DELETE removes a resource.','An idempotent operation has the same intended effect when repeated.','GET /api/courses?q=python\nPOST /api/enrollments\nPUT /api/courses/crs_web/progress'],['Agree on a contract.','An API contract specifies required fields and the expected response. JSON is a common representation. Validate input before changing state and return clear errors.','Use Content-Type: application/json for a JSON request body.','{"studentId":"stu_001","courseId":"crs_web"}'],['Communicate the outcome.','Status codes describe the result of a request. 200 means success, 201 means a resource was created, 404 means a resource was not found, and 409 means a conflict with current state.','A readable error message helps a client explain what to do next.','409 Conflict\n{"error":{"code":"ALREADY_ENROLLED","message":"Student is already enrolled"}}']],
 crs_sql:[['Organize information.','A table holds records in rows and attributes in columns. A primary key uniquely identifies a row. Related tables connect through keys.','Keep courses and enrollments in separate tables to avoid repeating course details.','courses(id, title)\nenrollments(id, student_id, course_id)'],['Ask a focused question.','SELECT chooses the columns to return. FROM identifies the table. WHERE filters records. Start with the exact question your result should answer.','Use parameterized queries for user-provided search values.','SELECT title FROM courses\nWHERE category = \'Data\';'],['Summarize records.','COUNT counts rows, SUM adds values, and AVG calculates a mean. GROUP BY produces one summary per group.','An aggregate summarizes many records into a smaller set of results.','SELECT course_id, COUNT(*) AS students\nFROM enrollments\nGROUP BY course_id;'],['Connect related tables.','JOIN connects records with matching values. An INNER JOIN returns matches from both tables; a LEFT JOIN also preserves unmatched rows from the left table.','Use explicit join conditions so the relationship is clear.','SELECT courses.title, enrollments.student_id\nFROM courses\nJOIN enrollments ON courses.id = enrollments.course_id;']],
 crs_git:[['Keep a meaningful checkpoint.','Git tracks changes in a repository. Stage the files you intend to save, inspect the staged changes, then create a commit with a meaningful message.','A commit records a snapshot of your project.','git add index.html\ngit diff --staged\ngit commit -m "Add course catalog"'],['Explore an idea safely.','A branch is a movable reference to a commit. Work on a branch to develop an idea, then merge it when the result is ready.','When changes conflict, inspect both sides and preserve the intended behavior.','git switch -c course-search\n# Make and commit changes\ngit switch main\ngit merge course-search'],['Share your history.','A remote is another repository. Fetch retrieves its commits. Push shares your local commits. Review changes before combining work from different contributors.','Fetching updates remote references without modifying your working files.','git fetch origin\ngit log --oneline --all\ngit push origin course-search'],['Make a small, reviewable change.','Inspect the current state before editing. Keep commits focused, review the diff, and verify the behavior your change affects.','Avoid committing unrelated files from another person’s work.','git status\ngit diff\n# Verify your change\ngit add <your-files>']]
};
function showLesson(id,index){const e=enrollments[id];if(!e||e.status!=='active')return toast('Complete payment to access lessons.');const c=courses.find(c=>c.id===id),l=lessonContent[id][index];openDialog(`${dialogTop(c.lessons[index],`LESSON ${index+1} OF 4`)}<div class="dialog-body lesson-text"><h3>${l[0]}</h3><p>${l[1]}</p><pre>${escapeHtml(l[3])}</pre><div class="notice">${l[2]}</div></div><div class="dialog-footer"><button class="secondary" data-action="classroom" data-id="${id}">← Course lessons</button><button class="primary" data-action="complete" data-id="${id}" data-index="${index}" ${e.completed.includes(index)?'disabled':''}>${e.completed.includes(index)?'Completed ✓':'Mark lesson complete ✓'}</button></div>`);}
const prompts={crs_web:'Describe a simple course page you would build. Include the HTML elements, two CSS rules, and one JavaScript interaction you would use.',crs_python:'Write a Python function that calculates progress from completed and total lessons. Explain how you would handle a total of zero.',crs_design:'Describe a course enrollment screen. Explain your visual hierarchy, spacing, primary action, and how you would display a payment error.',crs_api:'Design an enrollment endpoint. Specify the method, URI, request body, success response, and status code for a duplicate enrollment.',crs_sql:'Write a SQL query that counts active enrollments for each course. Explain the roles of WHERE and GROUP BY.',crs_git:'Describe a Git workflow for adding course search on a new branch. Include checking changes, creating a commit, and pushing the branch.'};
function showAssignment(id){const c=courses.find(c=>c.id===id),e=enrollments[id];if(!e||e.status!=='active')return toast('Complete payment to submit an assignment.');openDialog(`${dialogTop('A small challenge.','COURSE ASSIGNMENT')}<div class="dialog-body"><span class="tag">${c.title}</span><p>${prompts[id]}</p><label class="assignment-label" for="answer">Your answer</label><textarea id="answer" maxlength="10000" placeholder="Write your response here…" ${e.submission?'readonly':''}>${escapeHtml(e.submission||'')}</textarea><p class="muted">Written response · Up to 10,000 characters · No grading in this demo</p>${e.submission?`<p class="submitted">✓ Submitted on ${escapeHtml(new Date(e.submittedAt).toLocaleString())}</p>`:'<div id="assignment-error" role="alert"></div>'}</div><div class="dialog-footer"><button class="secondary" data-action="classroom" data-id="${id}">← Course lessons</button>${e.submission?'<span class="submitted">Submission received ✓</span>':`<button class="primary" data-action="submit" data-id="${id}">Submit assignment →</button>`}</div>`);}
function renderLearning(){const list=courses.filter(c=>enrollments[c.id]);main.innerHTML=`<section class="page-heading"><div class="eyebrow">ONE LESSON AT A TIME</div><h1>Your learning, in motion.</h1><p>Pick up where you left off. Every completed lesson counts.</p></section><div class="learning-list">${list.length?list.map(c=>{const e=enrollments[c.id];return `<article class="learning-card"><div class="learning-art" style="--art-bg:${c.bg};--art-ink:${c.ink}">${escapeHtml(c.symbol)}</div><div><span class="tag">${e.status==='active'?'Enrolled':'Payment pending'}</span><h3>${c.title}</h3><div class="progress-track"><div class="progress-fill" style="width:${e.completed.length*25}%"></div></div><span class="muted">${e.completed.length}/4 lessons · ${e.completed.length*25}% complete · Assignment ${e.submission?'submitted ✓':'not submitted'}</span></div><button class="primary" data-action="${e.status==='active'?'classroom':'checkout'}" data-id="${c.id}">${e.status==='active'?'Continue learning':'Complete demo payment'} →</button></article>`;}).join(''):'<div class="empty"><div class="little-book">▤</div><h2>Your next chapter is waiting.</h2><p>Enroll in a course to start tracking your progress.</p><button class="primary" data-view="courses">Explore courses →</button></div>'}</div><footer><span>Progress = completed lessons ÷ total lessons × 100</span><span>Saved in this browser only.</span></footer>`;}
function renderApi(){const rows=[['GET','/api/courses?q=python','Search courses','200'],['GET','/api/courses/{courseId}','Get course details','200 · 404'],['POST','/api/enrollments','Enroll in a course','201 · 400 · 404 · 409'],['GET','/api/students/{studentId}/progress','Get student progress','200 · 403'],['POST','/api/courses/{courseId}/assignments/{assignmentId}/submissions','Submit assignment','201 · 403 · 404 · 409 · 422'],['POST','/api/payments','Simulate payment','201 · 404 · 409 · 422'],['GET','/api/courses/{courseId}/content','Access course after payment','200 · 403 · 404'],['PUT','/api/courses/{courseId}/progress','Mark lesson complete (idempotent)','200 · 403 · 422']];main.innerHTML=`<section class="page-heading"><div class="eyebrow">ROUND 2 · LOW-LEVEL DESIGN</div><h1>The learning flow, explained.</h1><p>REST API contracts, enrollment examples, status codes, and the student sequence.</p></section><div class="notice api-intro">These are proposed REST endpoints. The website simulates their requests and responses in JavaScript; it does not run an HTTP API server. One fixed demo student is used, and demo records stay in this browser.</div><div class="api-table-wrap"><table><thead><tr><th>Method</th><th>URI</th><th>Purpose</th><th>Status codes</th></tr></thead><tbody>${rows.map(r=>`<tr><td><span class="method ${r[0]==='POST'?'post':''}">${r[0]}</span></td><td><code>${r[1]}</code></td><td>${r[2]}</td><td>${r[3]}</td></tr>`).join('')}</tbody></table></div><div class="api-grid"><section class="api-panel"><h2>Enrollment request</h2><p>Creates one enrollment per student and course. Paid course access remains locked until payment succeeds.</p><pre>POST /api/enrollments\nContent-Type: application/json\nAuthorization: Bearer &lt;student-token&gt;\n\n{\n  "studentId": "stu_001",\n  "courseId": "crs_web"\n}</pre><p>Production design: authenticate the student and require studentId to match the token subject. A unique constraint on (student_id, course_id) prevents duplicate enrollment.</p></section><section class="api-panel"><h2>Enrollment response</h2><p>201 Created · Location: /api/enrollments/enr_123</p><pre>{\n  "enrollmentId": "enr_123",\n  "studentId": "stu_001",\n  "courseId": "crs_web",\n  "status": "pending_payment",\n  "payment": {\n    "amount": 499,\n    "currency": "INR"\n  },\n  "createdAt": "2026-10-09T07:00:00Z"\n}</pre><p>Enrollment is created first. Its status becomes active only after confirmed payment. A payment failure preserves pending_payment for a retry.</p></section><section class="api-panel"><h2>Student → course access</h2><ol><li><strong>Search:</strong> Student → GET /api/courses?q=web → matching courses.</li><li><strong>View:</strong> Student → GET /api/courses/crs_web → syllabus and price.</li><li><strong>Enroll:</strong> Student → POST /api/enrollments → 201, pending_payment.</li><li><strong>Payment:</strong> Student → POST /api/payments → simulated success → active enrollment.</li><li><strong>Access:</strong> Student → GET /api/courses/crs_web/content → lessons. Unpaid access returns 403.</li><li><strong>Practice:</strong> Complete lessons, submit the assignment, and GET student progress.</li></ol><p>Production design: a verified payment-provider callback activates enrollment; the browser must never be allowed to declare payment successful.</p></section><section class="api-panel"><h2>Assignment submission</h2><pre>POST /api/courses/crs_web/assignments/asg_crs_web/submissions\nContent-Type: application/json\n\n{"content": "My written assignment response..."}\n\n201 Created\n{\n  "submissionId": "sub_123",\n  "assignmentId": "asg_crs_web",\n  "studentId": "stu_001",\n  "status": "submitted",\n  "submittedAt": "2026-10-09T07:15:00Z"\n}</pre><p>Require active enrollment and a nonempty answer of at most 10,000 characters. A second submission returns 409. This demo uses written answers and records receipt without grading.</p></section><section class="api-panel api-full"><h2>Suitable HTTP status codes</h2><p><strong>200 OK</strong> — Successful reads or a progress update. <strong>201 Created</strong> — Enrollment, payment, or submission created. <strong>400 Bad Request</strong> — Missing required enrollment fields. <strong>403 Forbidden</strong> — Unpaid course or another student’s progress. <strong>404 Not Found</strong> — Unknown course, enrollment, or assignment. <strong>409 Conflict</strong> — Duplicate enrollment, completed payment, or duplicate submission. <strong>422 Unprocessable Content</strong> — Invalid answer, lesson index, or failed simulated payment.</p><p>Production API design also uses <strong>401 Unauthorized</strong> for missing/invalid authentication, <strong>402 Payment Required</strong> where appropriate for a rejected payment, and <strong>500 Internal Server Error</strong> for unexpected server failures. Authentication and server failures are not simulated here.</p><details><summary>Progress response example · 200 OK</summary><pre>{\n  "studentId": "stu_001",\n  "courses": [{\n    "courseId": "crs_web",\n    "status": "active",\n    "completedLessons": 2,\n    "totalLessons": 4,\n    "progressPercent": 50,\n    "assignmentSubmitted": false\n  }]\n}</pre></details></section><section class="api-panel api-full"><h2>Live demo request log</h2><p>Actions in the website produce the simulated calls below. Open a course, enroll, or submit an assignment, then return here.</p><div class="log">${requests.length?requests.map(r=>`<details><summary class="log-row"><span class="status ${r.status>=400?'error':''}">${r.status}</span><strong>${r.method}</strong><span>${escapeHtml(r.path)}</span><span class="muted">${r.time}</span></summary><pre>${escapeHtml(JSON.stringify({request:r.body,response:r.data},null,2))}</pre></details>`).join(''):'<p>No requests yet. Explore a course to make the first call.</p>'}</div></section></div>`;}
document.addEventListener('click',event=>{
 const b=event.target.closest('button');if(!b)return;
 if(b.dataset.view){showView(b.dataset.view);return;}
 if(b.dataset.category){category=b.dataset.category;document.querySelectorAll('[data-category]').forEach(el=>el.classList.toggle('active',el===b));api('GET',`/api/courses?q=${encodeURIComponent(query)}`);renderCatalog();return;}
 if(b.dataset.course){showCourse(b.dataset.course);return;}
 const id=b.dataset.id,index=Number(b.dataset.index);
 switch(b.dataset.action){case 'close':dialog.close();break;case 'enroll':enroll(id);break;case 'checkout':showCheckout(id);break;case 'pay':pay(id,true);break;case 'decline':pay(id,false);break;case 'classroom':showClassroom(id);break;case 'lesson':showLesson(id,index);break;case 'assignment':showAssignment(id);break;case 'complete':{const r=api('PUT',`/api/courses/${id}/progress`,{lessonIndex:index});if(r.status===200){toast('Lesson complete. Your progress is saved.');showClassroom(id);if(view==='learning')renderLearning();}else toast(r.data.error.message);break;}case 'submit':{const r=api('POST',`/api/courses/${id}/assignments/asg_${id}/submissions`,{content:document.querySelector('#answer').value});if(r.status===201){toast('Assignment submitted. Nice work.');showAssignment(id);if(view==='learning')renderLearning();}else document.querySelector('#assignment-error').innerHTML=`<p class="error-text">${escapeHtml(r.data.error.message)}</p>`;break;}}
});
document.addEventListener('input',event=>{if(event.target.id==='search'){query=event.target.value;renderCatalog();clearTimeout(api.searchTimer);api.searchTimer=setTimeout(()=>api('GET',`/api/courses?q=${encodeURIComponent(query)}`),300);}});
document.addEventListener('keydown',event=>{if(event.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)&&view==='courses'&&!dialog.open){event.preventDefault();document.querySelector('#search').focus();}});
dialog.addEventListener('click',event=>{if(event.target===dialog){const rect=dialog.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)dialog.close();}});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(['courses','learning','api'].includes(next)&&next!==view)showView(next);});
updateCount();if(['learning','api'].includes(location.hash.slice(1)))showView(location.hash.slice(1));
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const tool={name:'search_courses',title:'Search learning courses',description:'Search the demo course catalog and update the visible search results. Does not enroll or pay.',inputSchema:{type:'object',properties:{query:{type:'string',maxLength:200}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){if(!input||typeof input.query!=='string'||input.query.length>200)throw new Error('query must be a string of at most 200 characters');query=input.query;category='All';showView('courses');const r=api('GET',`/api/courses?q=${encodeURIComponent(query)}`);return {courses:r.data.courses.map(c=>({id:c.id,title:c.title,price:c.price}))};}};try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
